entries[377449] = { ["name"] = "Decoration of Flame", ["text"] = "Instant 2 min cooldown\nStomp the ground, commanding flames to radiate outward from your position, dealing 1690 Fire damage split between all enemies struck and granting you a 3155 shield for 30 sec. After a delay, the flames return, dealing the same damage and refreshing the shield.\n\nDamage and absorption are increased for each enemy struck, up to 5 enemies." }
