entries[377452] = { ["name"] = "Whispering Incarnate Icon", ["text"] = "Succumb to the Icon's whispers and become Infused with Frost , increasing your Critical Strike by 57 .\n\nFighting alongside allies who are Infused with Earth or Fire has a chance to grant you 16 of their Infusion's stat for 12 sec.\n\nInfusion based on your current specialization.\n(1.5s cooldown)" }
entries[377453] = { ["name"] = "Storm-Eater's Boon", ["text"] = "Instant 3 min cooldown\nAccept the storm, becoming a Primal Air Elemental and immobilizing yourself for 10 sec.\n\nWhile in this form, the winds around you deal 311 Nature damage per second to all enemies within 10 yards, intensifying by 10% each second until the transformation subsides." }
entries[377454] = { ["name"] = "Rumbling Ruby", ["text"] = "Approximately 5 procs per minute\nYour attacks slowly build Concussive Force, granting 3 attack power per stack.\n\nAt 10 stacks, your next 3 melee abilities emit a shockwave in front of you, dealing 903 bonus Nature damage to all enemies in a line. Shockwaves deal more damage to enemies at high health.\n(500ms cooldown)" }
entries[377455] = { ["name"] = "Iceblood Deathsnare", ["text"] = "45 yd range\nInstant 2 min cooldown\nDeal 2197 Frost damage to your target, encasing them and nearby enemies in a Crystalline Web for 15 sec. Webbed enemies are slowed by 15% and take 174 Frost damage when any enemy in the web is struck.\n\nDamage is increased for each webbed enemy, up to 5. Damage per target is reduced beyond 5 enemies." }
entries[377456] = { ["name"] = "Way of Controlled Currents", ["text"] = "Your critical strikes have a chance to build Static Electricity, granting 2% attack speed per stack. This effect may occur every 1 sec.\n\nAt 10 stacks lightning surges through you, increasing your movement speed by 30% for 12 seconds. While surging, your auto attacks jolt your target and 1 nearby enemy for 319 Nature damage.\n\nWhen this effect fades, you become grounded for 1 min and unable to generate Static Electricity.\n(1.5s cooldown)" }
